// Aggregate all 7 agent results (robust with checks)
const items = $input.all();

// Safe access with defaults
const getJson = (index, defaultObj = {}) => (items[index] && items[index].json) || defaultObj;

const plannerData = getJson(0);
const risksData = getJson(1);
const imageData = getJson(2);
const progressData = getJson(3);
const healthData = getJson(4);
const metricsData = getJson(5);
const digestData = getJson(6);

// Extract key information
const report = {
  timestamp: new Date().toISOString(),
  task: $('Set Input Variables').item.json.task_description || 'No task',

  planning: {
    subtasks: plannerData.subtasks || [],
    subtasks_count: (plannerData.subtasks || []).length,
    reasoning_steps: (plannerData.reasoning || []).length
  },

  risks: {
    total_risks: risksData.total_risks || 0,
    top_risks: (risksData.detected_risks || []).slice(0, 3)
  },

  architecture_analysis: {
    provider: imageData.vision_provider || 'fallback',
    summary: (imageData.analysis || '').substring(0, 200) + '...',
    fallback_used: imageData.fallback_used || false
  },

  project_velocity: {
    status: progressData.velocity_status || 'unknown',
    completion_rate: progressData.completion_rate || 0,
    total_issues: progressData.total_issues || 0
  },

  system_health: {
    status: healthData.overall_status || healthData.status || 'unknown',
    fallback_used: healthData.fallback_used || false
  },

  system_metrics: {
    total_requests: metricsData.total_requests || metricsData.processed_tasks || 0,
    errors: metricsData.errors || metricsData.error_count || 0
  },

  daily_digest: {
    date: digestData.date || new Date().toISOString().split('T')[0],
    summary: digestData.summary || 'No digest available',
    fallback_used: digestData.fallback_used || false
  },

  recommendations: []
};

// Generate smart recommendations
if (report.risks.total_risks > 5) report.recommendations.push('⚠️ High number of risks - prioritize mitigation');
if (report.project_velocity.completion_rate < 50) report.recommendations.push('📊 Project velocity at risk - review resources');
if (report.planning.subtasks_count > 7) report.recommendations.push('📋 Consider breaking down into smaller tasks');
if (report.architecture_analysis.fallback_used) report.recommendations.push('🖼️ Vision analysis unavailable - manual review needed');
if (report.system_health.status !== 'healthy' && report.system_health.status !== 'unknown') report.recommendations.push('🔴 System health issue detected');
if (report.system_metrics.errors > 0) report.recommendations.push('⚠️ System errors detected - check logs');
if (report.daily_digest.fallback_used) report.recommendations.push('📝 Daily digest fallback used');
if (report.recommendations.length === 0) report.recommendations.push('✅ All systems operational - proceed with implementation');

return { json: report };

